import { useStore } from 'zustand'
import { createStore } from 'zustand'
import type { TreeItemIndex } from 'react-complex-tree'
export type TabState = {
	activeTabList: string[]
	activeTab: string | null
	hasInitialized: boolean
}

type CodeViewStore = {
	tabState: TabState
	setTabState: (tabState: TabState | ((prev: TabState) => TabState)) => void

	filePath: string | null
	setFilePath: (filePath: string | null) => void

	expandedFolders: TreeItemIndex[]
	setExpandedFolders: (
		folders: TreeItemIndex[] | ((prev: TreeItemIndex[]) => TreeItemIndex[])
	) => void
	reset: () => void
}

const initialTabState: TabState = {
	activeTabList: [],
	activeTab: null,
	hasInitialized: false
}

export const codeViewStore = createStore<CodeViewStore>((set, get) => ({
	tabState: initialTabState,
	setTabState: (tabState) => {
		if (typeof tabState === 'function') {
			set({ tabState: tabState(get().tabState) })
		} else {
			set({ tabState })
		}
	},

	filePath: null,
	setFilePath: (filePath) => set({ filePath }),

	expandedFolders: [],
	setExpandedFolders: (folders) => {
		if (typeof folders === 'function') {
			set({ expandedFolders: folders(get().expandedFolders) })
		} else {
			set({ expandedFolders: folders })
		}
	},
	reset: () => {
		set({
			tabState: initialTabState,
			filePath: null,
			expandedFolders: []
		})
	}
}))

export const useCodeViewStore = <T>(selector: (state: CodeViewStore) => T) =>
	useStore(codeViewStore, selector)
